package br.com.mecaniQA.api.service;
import br.com.mecaniQA.api.Repository.*;import br.com.mecaniQA.api.model.*;import br.com.mecaniQA.api.Enums.*;import java.util.*;import org.springframework.stereotype.Service;
@Service public class PedidoPecasService {private final PedidoPecasRepository repo=PedidoPecasRepository.getInstance();private final ItemPedidoRepository itens=ItemPedidoRepository.getInstance();private final OrdemServicoRepository ordens=OrdemServicoRepository.getInstance();private final PecasRepository pecas=PecasRepository.getInstance();public OrdemServico buscarOrdem(Long id){return ordens.buscarPorNumero(id);}public Pecas buscarPeca(Long id){return pecas.buscarPorCodigo(id);}public PedidoPecas cadastrar(PedidoPecas x){return repo.cadastrar(x);}public PedidoPecas buscarPorNumero(Long id){return repo.buscarPorNumero(id);}public List<PedidoPecas>listarTodos(){return repo.listarTodos();}public PedidoPecas atualizarStatus(Long id,StatusPedidoPecas s){return repo.atualizarStatus(id,s);}public PedidoPecas deletar(Long id){return repo.deletar(id);}public ItemPedido cadastrarItem(ItemPedido x){return itens.cadastrar(x);}}
